### Pure Python কোডের যাচাই করা Output
- `Sample #3 retrieved decision: {'emitted': True, 'reason': 'unverified_hypothesis'}`
- `Sample #3 used_bytes / passages / tokens: 857 / 3 / 8`
- `Sample #3 empty_budget decision: {'emitted': False, 'reason': 'no_context'}`
- `Total golden cases passing all Stage Contracts: 18`

### Option B — Python `dataclasses` দিয়ে স্পষ্ট Stage Interface Contract লেখা
বড় Production কোডবেসে (যেমন `FastAPI` বা `PyTorch` সার্ভিংয়ে) সাধারণ `dict`-এর বদলে `dataclass` দিয়ে প্রতিটি Stage-এর সীমানা টাইপ-নিরাপদ করা হয়, যাতে ভুল ফিল্ড বা ভুল একক (`bytes` বনাম `tokens`) ঢুকলেই কোড সঙ্গে সঙ্গে ধরে ফেলে:

```python
from dataclasses import dataclass

@dataclass(frozen=True)
class PackOutput:
    selected_ids: list
    used_bytes: int
    max_budget: int = 1024

@dataclass(frozen=True)
class GateDecision:
    emitted: bool
    reason: str

def run_policy(pack_out, quotes_exact, format_valid, p_first, tau=0.0):
    if len(pack_out.selected_ids) == 0:
        return GateDecision(False, "no_context")
    if not quotes_exact:
        return GateDecision(False, "citation_mismatch")
    if not format_valid:
        return GateDecision(False, "invalid_format")
    if p_first < tau:
        return GateDecision(False, "low_confidence")
    return GateDecision(True, "unverified_hypothesis")

p = PackOutput(selected_ids=["2739854:0-2", "4414547:7-9"], used_bytes=612)
print(run_policy(p, True, True, 0.7919, tau=0.0))
print(run_policy(PackOutput([], 0), True, True, 0.99, tau=0.0))
```

**Pure Python যাচাই করা Output:**
- `GateDecision(emitted=True, reason='unverified_hypothesis')`
- `GateDecision(emitted=False, reason='no_context')` *(খেয়াল করুন: `p_first = 0.99` হলেও খালি `PackOutput` ঢোকায় Gate সঙ্গে সঙ্গে `no_context` রিটার্ন করেছে!)*

import math

# ১) আমাদের ৩-নথির হাতে-কলমে ডেটাসেট (কোনো numpy বা pandas ছাড়াই!)
docs = {
    104: {"cell": 2, "dna": 1},
    102: {"cell": 2, "dna": 1},
    105: {"rna": 3},
}
idf = {"cell": 1.2, "dna": 1.8, "rna": 1.5}

def build_unit_weights(tf_map):
    weights = {}
    sq_sum = 0.0
    for term, count in tf_map.items():
        if term in idf and count > 0:
            w = (1.0 + math.log(count)) * idf[term]
            weights[term] = w
            sq_sum += w * w
    if sq_sum == 0.0:
        return {}
    norm = math.sqrt(sq_sum)
    unit = {}
    for term, w in weights.items():
        unit[term] = w / norm
    return unit

def retrieve_top_k(query_tf, k=10):
    qv = build_unit_weights(query_tf)
    if not qv:
        return []
    scored = []
    for doc_id, dtf in docs.items():
        dv = build_unit_weights(dtf)
        dot = 0.0
        for term, qw in qv.items():
            if term in dv:
                dot += qw * dv[term]
        if dot > 0.0:
            scored.append((dot, doc_id))
    # Deterministic sort: বড় score আগে, সমান হলে ছোট numeric doc_id আগে!
    def sort_key(pair):
        return (-pair[0], pair[1])
    scored.sort(key=sort_key)
    return scored[:k]

hits = retrieve_top_k({"cell": 1, "dna": 1}, k=10)
empty_hits = retrieve_top_k({}, k=10)
oov_hits = retrieve_top_k({"myocardial": 1, "infarction": 1}, k=10)

assert len(hits) == 2 and hits[0][1] == 102 and hits[1][1] == 104
assert empty_hits == [] and oov_hits == []

pretty = []
for s, d in hits:
    pretty.append((round(s, 4), d))
print("Top hits (score, doc_id):", pretty)
print("Empty query hits:", empty_hits, "| OOV query hits:", oov_hits)

import math

# ১) Gold-free Deterministic Runtime Policy (capstone_workflow.py-এর হুবহু সমতুল্য!)
def runtime_policy(generation, quotes_exact, has_context, threshold=0.0):
    if not math.isfinite(threshold) or threshold < 0.0 or threshold > 1.0:
        raise ValueError("threshold must be in [0, 1]")
    if not has_context:
        return {"emitted": False, "reason": "no_context"}
    if not quotes_exact:
        return {"emitted": False, "reason": "citation_mismatch"}
    if not generation["format_valid"]:
        return {"emitted": False, "reason": "invalid_format"}
    if generation["first_token_confidence"] < threshold:
        return {"emitted": False, "reason": "low_confidence"}
    return {"emitted": True, "reason": "unverified_hypothesis"}

# ২) প্রতিটি শাখা ও অগ্রাধিকার ক্রম পরীক্ষা করি
g_ok = {"format_valid": True, "first_token_confidence": 0.80}
g_bad = {"format_valid": False, "first_token_confidence": 0.99}

r_emit = runtime_policy(g_ok, True, True, 0.0)
r_ctx = runtime_policy(g_ok, False, False, 0.9)   # দুটোই ব্যর্থ, কিন্তু no_context সবার আগে!
r_cit = runtime_policy(g_ok, False, True, 0.0)
r_fmt = runtime_policy(g_bad, True, True, 0.0)
r_low = runtime_policy(g_ok, True, True, 0.9)

assert r_emit["emitted"] is True and r_emit["reason"] == "unverified_hypothesis"
assert r_ctx["reason"] == "no_context"
assert r_cit["reason"] == "citation_mismatch"
assert r_fmt["reason"] == "invalid_format"
assert r_low["reason"] == "low_confidence"

# ৩) First-token Confidence (0.99) বনাম 8-token Joint Sequence Probability হিসাব
token_probs = [0.99, 0.5, 0.5, 0.5, 0.5, 0.5, 0.5, 0.5]
log_p = 0.0
for p in token_probs:
    log_p += math.log(p)
joint_p = math.exp(log_p)
assert math.isclose(joint_p, 0.99 * (0.5 ** 7), rel_tol=1e-12)

print("All 5 policy branches:", r_emit["reason"], r_ctx["reason"], r_cit["reason"], r_fmt["reason"], r_low["reason"])
print("First-token p:", token_probs[0], "| 8-token joint p:", round(joint_p, 9), "| Passes tau=0.9?:", token_probs[0] >= 0.9)

import json
from pathlib import Path

root = Path("assets/datasets/scifact_rag")
lab = json.loads((root / "capstone_lab.json").read_text(encoding="utf-8"))

# ১) Sample #3-এর ১ম নির্বাচিত উদ্ধৃতিটি নিই এবং মূল corpus.jsonl থেকে তার আসল নথি খুঁজি
quote = dict(lab["samples"][3]["cases"]["retrieved"]["pack"]["selected"][0])
target_doc_id = str(quote["doc_id"])

corpus_subset = {}
with (root / "corpus.jsonl").open(encoding="utf-8") as f:
    for line in f:
        row = json.loads(line)
        did = str(row["doc_id"])
        if did == target_doc_id:
            corpus_subset[did] = row["abstract"]
            break

# ২) Deterministic Source Resolver ও Exact Quote Auditor
def audit_quote(doc_id, start, end, shown_text, source_map):
    sents = source_map.get(str(doc_id))
    if sents is None:
        return {"resolvable": False, "exact_quote": False}
    if not (0 <= start < end <= len(sents)):
        return {"resolvable": False, "exact_quote": False}
    original = " ".join(sents[start:end])
    return {"resolvable": True, "exact_quote": (shown_text == original)}

# ৩) ৫টি আবশ্যিক Unit Test কেস যাচাই করি
orig_res = audit_quote(quote["doc_id"], quote["start"], quote["end"], quote["text"], corpus_subset)
mut_res = audit_quote(quote["doc_id"], quote["start"], quote["end"], quote["text"] + " [edited]", corpus_subset)
oob_res = audit_quote(quote["doc_id"], quote["start"], 999, quote["text"], corpus_subset)
empty_res = audit_quote(quote["doc_id"], 2, 2, "", corpus_subset)
unk_res = audit_quote("99999999", 0, 1, "anything", corpus_subset)

assert orig_res == {"resolvable": True, "exact_quote": True}
assert mut_res == {"resolvable": True, "exact_quote": False}
assert oob_res == {"resolvable": False, "exact_quote": False}
assert empty_res == {"resolvable": False, "exact_quote": False}
assert unk_res == {"resolvable": False, "exact_quote": False}

citation_tag = f"[{quote['doc_id']}:{quote['start']}-{quote['end']}]"
print("Citation tag:", citation_tag, "| Doc sentences:", len(corpus_subset[target_doc_id]))
print("Original audit:", orig_res)
print("Edited mutation audit:", mut_res)
print("OOB / Empty / Unknown:", oob_res["resolvable"], empty_res["resolvable"], unk_res["resolvable"])

import itertools
import json
from pathlib import Path

# ১) আমাদের Gold-free Runtime Policy
def policy(format_valid, p_first, exact_quote, has_context, tau=0.9):
    if not has_context:
        return {"emitted": False, "reason": "no_context"}
    if not exact_quote:
        return {"emitted": False, "reason": "citation_mismatch"}
    if not format_valid:
        return {"emitted": False, "reason": "invalid_format"}
    if p_first < tau:
        return {"emitted": False, "reason": "low_confidence"}
    return {"emitted": True, "reason": "unverified_hypothesis"}

# ২) ১৬-ঘরের পূর্ণাঙ্গ Truth Table (2^4 = 16) পরীক্ষা করি
total_cases = 0
emitted_count = 0
reason_counts = {}

for ctx, exact, fmt, conf in itertools.product([False, True], [False, True], [False, True], [0.2, 0.99]):
    res = policy(fmt, conf, exact, ctx, tau=0.9)
    expected_emit = ctx and exact and fmt and (conf >= 0.9)
    assert res["emitted"] == expected_emit
    total_cases += 1
    if res["emitted"]:
        emitted_count += 1
    reason = res["reason"]
    reason_counts[reason] = reason_counts.get(reason, 0) + 1

assert total_cases == 16 and emitted_count == 1
assert reason_counts == {
    "no_context": 8,
    "citation_mismatch": 4,
    "invalid_format": 2,
    "low_confidence": 1,
    "unverified_hypothesis": 1,
}

# ৩) ১৮টি Golden Trace-এ Numerical ও Runtime Contract Invariant যাচাই
lab = json.loads(
    Path("assets/datasets/scifact_rag/capstone_lab.json").read_text(encoding="utf-8")
)
checked_traces = 0
for sample in lab["samples"]:
    for case in sample["cases"].values():
        assert len(case["features"]) == 256
        assert len(case["generation"]["trace"]) <= 12
        checked_traces += 1

assert checked_traces == 18
print("Truth table cases / emitted:", total_cases, "/", emitted_count)
print("Exact reason breakdown:", reason_counts)
print("Checked golden traces:", checked_traces, "| Numerical and runtime contracts verified.")
